-- Puts slot equipment on the units V3_8 loaded where the critical slots put it (importers skill, bugs 8 and
-- 22). Until 2026-11-11 the mech reader kept equipment read from the slots once per mech, at the first
-- location it was in, and all jump jets at the first location they were in: the Catapult CPLT-C1b had one
-- CASE (it has one in each side torso) and the Paladin PAL-2 six jump jets in its left torso (two are, two
-- are in the right torso and one in each leg). Now equipment in several locations is an item in each,
-- equipment counted by slots (jump jets, UMUs, A-pods, coolant pods, ...) is at its own slot's location,
-- and equipment MegaMek spreads over the mech (TSM, Null Signature System) stays one item at its first
-- location (bug 30).
--
-- Generated from a database V3_8 to V3_13 loaded and the fixed importer then re-imported (mechs, then
-- vehicles, mm-data at d195e171b3c87801c8dbc5ffcb5f763e5da57483), by comparing each unit's items before
-- and after: on 2,031 units 5,202 items moved and 879 were added, none went and nothing else changed. Each
-- group below is one unit's items of one equipment with the same attributes, with how many each location
-- should have. Items are moved, added or removed only by comparing those counts with what's stored, so
-- running it on a database that already has them changes nothing.
-- Data migrations after V3_8 update what's stored; see the importers skill.

-- 1. Each unit's items that change, as a group of one equipment with the same attributes, and how many
-- of them each location should have
CREATE TEMPORARY TABLE v3_14_group (gid integer PRIMARY KEY, megamek_uuid uuid, name varchar(255), tech varchar(255),
  omni_pod boolean, rear_facing boolean, tonnage double precision, turret_equipped boolean, fire_control varchar(255),
  jump_boost integer, drones integer, mash_theaters integer);
CREATE TEMPORARY TABLE v3_14_target (gid integer, location varchar(255), n integer);

-- 2. The items each group has now
CREATE TEMPORARY TABLE v3_14_current AS
  SELECT g.gid, u.id AS unit_id, ue.id, ue.location
  FROM v3_14_group g
  JOIN unit u ON u.megamek_uuid = g.megamek_uuid
  JOIN unit_mech_equipment ume ON ume.unit_id = u.id
  JOIN unit_equipment ue ON ue.id = ume.mech_equipment_id
  JOIN equipment e ON e.id = ue.equipment_id
  WHERE e.name = g.name AND e.tech = g.tech AND ue.omni_pod = g.omni_pod AND ue.rear_facing = g.rear_facing
    AND ue.tonnage = g.tonnage AND ue.turret_equipped = g.turret_equipped
    AND ue.fire_control IS NOT DISTINCT FROM g.fire_control AND ue.jump_boost IS NOT DISTINCT FROM g.jump_boost
    AND ue.drones IS NOT DISTINCT FROM g.drones AND ue.mash_theaters IS NOT DISTINCT FROM g.mash_theaters;

-- 3. Items a location has too many of, and places a location is missing one, each numbered within its group
CREATE TEMPORARY TABLE v3_14_surplus AS
  SELECT c.gid, c.id, row_number() OVER (PARTITION BY c.gid ORDER BY c.location, c.id) AS k
  FROM (SELECT c.*, row_number() OVER (PARTITION BY c.gid, c.location ORDER BY c.id) AS r FROM v3_14_current c) c
  LEFT JOIN v3_14_target t ON t.gid = c.gid AND t.location IS NOT DISTINCT FROM c.location
  WHERE c.r > coalesce(t.n, 0);
CREATE TEMPORARY TABLE v3_14_missing AS
  SELECT t.gid, t.location, row_number() OVER (PARTITION BY t.gid ORDER BY t.location, s.i) AS k
  FROM v3_14_target t
  CROSS JOIN LATERAL generate_series(1, t.n - (SELECT count(*) FROM v3_14_current c
    WHERE c.gid = t.gid AND c.location IS NOT DISTINCT FROM t.location)) s(i);

-- 4. Move items to where they're missing (the Paladin's jump jets out of the left torso)
UPDATE unit_equipment ue SET location = m.location
  FROM v3_14_surplus s JOIN v3_14_missing m ON m.gid = s.gid AND m.k = s.k
  WHERE ue.id = s.id;

-- 5. Add the items still missing (the Catapult's second CASE), on a unit that has the equipment row
CREATE TEMPORARY TABLE v3_14_new AS
  SELECT gen_random_uuid() AS id, u.id AS unit_id, g.*, m.location AS new_location,
    (SELECT e.id FROM equipment e WHERE e.name = g.name AND e.tech = g.tech ORDER BY e.id LIMIT 1) AS equipment_id
  FROM v3_14_missing m
  JOIN v3_14_group g ON g.gid = m.gid
  JOIN unit u ON u.megamek_uuid = g.megamek_uuid
  WHERE m.k > (SELECT count(*) FROM v3_14_surplus s WHERE s.gid = m.gid);
    jump_boost, drones, mash_theaters)
  SELECT id, new_location, omni_pod, rear_facing, tonnage, turret_equipped, equipment_id, fire_control, jump_boost,
    drones, mash_theaters
  FROM v3_14_new WHERE equipment_id IS NOT NULL;
  SELECT unit_id, id FROM v3_14_new WHERE equipment_id IS NOT NULL;

-- 6. Remove the items left over
CREATE TEMPORARY TABLE v3_14_leftover AS
  SELECT s.id FROM v3_14_surplus s
  WHERE s.k > (SELECT count(*) FROM v3_14_missing m WHERE m.gid = s.gid);
DELETE FROM unit_mech_equipment WHERE mech_equipment_id IN (SELECT id FROM v3_14_leftover);
DELETE FROM unit_equipment WHERE id IN (SELECT id FROM v3_14_leftover);

DROP TABLE v3_14_group, v3_14_target, v3_14_current, v3_14_surplus, v3_14_missing, v3_14_new, v3_14_leftover;
